const searchConversationsFTSSnippets = `-- name: SearchConversationsFTSSnippets :many
WITH ranked AS (
  SELECT m.conversation_id, m.message_id,
         row_number() OVER (
           PARTITION BY m.conversation_id
           ORDER BY ts_rank(hits.document, websearch_to_tsquery('english', $1::text)) DESC
         ) AS rank_in_conversation
  FROM messages m
  JOIN messages_fts hits ON hits.message_id = m.message_id
  WHERE hits.document @@ websearch_to_tsquery('english', $1::text)
    AND m.conversation_id = ANY($4::text[])
)
SELECT ranked.conversation_id, ranked.message_id,
       ts_headline('english', messages_fts.text, websearch_to_tsquery('english', $1::text),
         'StartSel=' || $2::text || ', StopSel=' || $3::text ||
         ', MaxWords=16, MinWords=4, FragmentDelimiter=...')::text AS snippet
FROM messages_fts
JOIN ranked ON ranked.message_id = messages_fts.message_id
WHERE ranked.rank_in_conversation = 1
`

